<template><view class="m2-page"><view class="m2-card"><text class="m2-heading">支持作者</text><text class="m2-body">{{book?.title||'加载中…'}} · {{book?.authorName||''}}</text><text class="m2-muted">可用余额 ¥ {{money(balance)}} · 打赏全额计入作者余额</text></view><view class="m2-card"><view class="amounts"><view v-for="n in [100,500,1000,2000]" :key="n" class="amount" :class="{active:String(amount)===String(n/100)}" @click="choose(n)">¥ {{n/100}}</view></view><input class="m2-input" v-model="amount" type="digit" placeholder="自定义金额，最多1000元" :disabled="busy" @input="changed"/><textarea class="m2-textarea" v-model="message" maxlength="100" placeholder="给作者留句话（选填）" :disabled="busy" @input="changed"/><button class="m2-primary" :disabled="busy||!book" :loading="busy" @click="submit">确认打赏</button><text class="m2-link" @click="wallet">余额不足？前往充值</text><text v-if="error" class="m2-error">{{error}}</text></view></view></template>
<script>
import {getWallet,tipBook} from '../../api/wallet'
import {getBookDetail} from '../../api/book'
import {money,requestId} from '../../utils/money'
import {requireLogin} from '../../utils/auth'
export default{data(){return{bookId:null,book:null,balance:0,amount:'1',message:'',id:null,busy:false,error:''}},onLoad(o){this.bookId=o.bookId},async onShow(){if(!requireLogin())return;try{const [b,w]=await Promise.all([getBookDetail(this.bookId),getWallet()]);this.book=b;this.balance=w.balance;const draft=uni.getStorageSync(this.key());if(draft){this.amount=draft.amount;this.message=draft.message;this.id=draft.id}}catch(e){this.error=e.msg}},methods:{money,key(){return 'tipDraft:'+uni.getStorageSync('userInfo')?.id+':'+this.bookId},changed(){this.id=null;uni.removeStorageSync(this.key())},choose(n){if(this.busy)return;this.amount=String(n/100);this.changed()},wallet(){uni.navigateTo({url:'/pages/wallet/index'})},submit(){if(this.busy||!requireLogin())return;const text=String(this.amount);if(!/^\d{1,4}(\.\d{1,2})?$/.test(text)){this.error='请输入最多两位小数的金额';return}const [yuan,cent='']=text.split('.');const fen=Number(yuan)*100+Number(cent.padEnd(2,'0'));if(fen<1||fen>100000){this.error='单次打赏为0.01至1000元';return}
uni.showModal({title:'确认打赏',content:'向《'+this.book.title+'》作者打赏 ¥ '+money(fen)+'？',success:async r=>{if(!r.confirm||this.busy)return;this.busy=true;this.error='';this.id=this.id||requestId();uni.setStorageSync(this.key(),{id:this.id,amount:this.amount,message:this.message});try{const d=await tipBook(this.bookId,{amount:fen,message:this.message,requestId:this.id});this.balance=d.balance;this.changed();uni.showToast({title:d.alreadyProcessed?'该笔打赏已完成':'打赏成功',icon:'none'})}catch(e){this.error=e.msg||'结果暂未确认，重试将使用同一提交标识'}finally{this.busy=false}}})}}}
</script><style scoped>.amounts{display:flex;gap:12rpx;margin-bottom:24rpx}.amount{flex:1;padding:24rpx 0;text-align:center;border:2rpx solid #eaded6;border-radius:12rpx}.active{border-color:#b5533d;color:#b5533d;background:#fcf2e9}</style>
